  async function deliverMessage(input: {
    callbacks: CreateChatSdkEndpointRuntimeOptions["callbacks"];
    endpointId: string;
    message: Message;
    provider?: ChatProvider;
    providerUpdateId?: number;
    thread: Thread;
    trigger: ChatSdkMessageTrigger;
  }) {
    await input.callbacks.onMessage({
      endpointId: input.endpointId,
      provider: input.provider ?? "slack",
      providerUpdateId: input.providerUpdateId,
      thread: input.thread,
      message: input.message,
      trigger: input.trigger,
    });
  }

  function attachFakeGitHubIssueCommentWebhook(input: {
    botUsername: string;
    callbacks: CreateChatSdkEndpointRuntimeOptions["callbacks"];
    endpointId: string;
    runtime: FakeEndpointRuntime;
  }) {
    input.runtime.webhookHook = async (request) => {
      const payload = (await request.clone().json()) as {
        action?: unknown;
        comment?: {
          body?: unknown;
          created_at?: unknown;
          id?: unknown;
          updated_at?: unknown;
          user?: { id?: unknown; login?: unknown };
        };
        issue?: { number?: unknown; pull_request?: unknown };
        repository?: {
          full_name?: unknown;
          name?: unknown;
          owner?: { login?: unknown };
        };
        sender?: { id?: unknown; login?: unknown };
      };
      if (payload.action !== "created") return;
      const fullName =
        typeof payload.repository?.full_name === "string"
          ? payload.repository.full_name
          : typeof payload.repository?.owner?.login === "string" &&
              typeof payload.repository.name === "string"
            ? `${payload.repository.owner.login}/${payload.repository.name}`
            : null;
      const issueNumber = payload.issue?.number;
      const messageId = payload.comment?.id;
      const text = payload.comment?.body;
      if (
        !fullName ||
        typeof issueNumber !== "number" ||
        (typeof messageId !== "number" && typeof messageId !== "string") ||
        typeof text !== "string"
      ) {
        return;
      }
      const mentionNames = new Set([
        input.botUsername,
        input.botUsername.replace(/\[bot\]$/i, ""),
      ]);
      const mentioned = [...mentionNames].some((identity) =>
        new RegExp(
          `(?<!\\w)@${identity.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}(?![\\w-])`,
          "i",
        ).test(text),
      );
      const thread = makeThread({
        channelId: fullName,
        id: payload.issue?.pull_request
          ? `github:${fullName}:${issueNumber}`
          : `github:${fullName}:issue:${issueNumber}`,
        name: fullName,
      }).thread;
      const message = makeMessage({
        id: String(messageId),
        raw: payload,
        text,
        mentioned,
        userId: String(payload.sender?.id ?? payload.comment?.user?.id ?? "42"),
        userName: String(
          payload.sender?.login ?? payload.comment?.user?.login ?? "octocat",
        ),
      });
      const createdAt = payload.comment?.created_at;
      if (typeof createdAt === "string")
        message.metadata.dateSent = new Date(createdAt);
      await deliverMessage({
        callbacks: input.callbacks,
        endpointId: input.endpointId,
        message,
        provider: "github",
        thread,
        trigger: mentioned ? "mention" : "unaddressed_message",
      });
    };
  }

  it("creates a channel-purpose connection and rejects attempts to change its assigned agent", async () => {
    const fixture = await seedCompany();
    const { service } = createService();
    const app = routesApp(db, fixture.companyId, service);

    const createResponse = await request(app)
      .post(`/api/companies/${fixture.companyId}/chat-endpoints`)
      .send({ provider: "slack", assignedAgentId: fixture.assignedAgentId })
      .expect(201);

    expect(createResponse.body).toMatchObject({
      provider: "slack",
      assignedAgentId: fixture.assignedAgentId,
      assignedAgentName: "Maya",
      status: "draft",
      setup: { command: expect.stringMatching(/^\/maya-[a-z0-9]{6}$/) },
    });
    const createdCommand = createResponse.body.setup.command as string;
    const [connection] = await db
      .select()
      .from(toolConnections)
      .where(eq(toolConnections.id, createResponse.body.connectionId));
    expect(connection).toMatchObject({
      connectionPurpose: "channel",
      transport: "chat_sdk",
    });

    await request(app)
      .patch(`/api/chat-endpoints/${createResponse.body.id}`)
      .send({ assignedAgentId: fixture.replacementAgentId })
      .expect(400);
    const [stored] = await db
      .select({
        assignedAgentId: chatEndpoints.assignedAgentId,
        setup: chatEndpoints.setup,
      })
      .from(chatEndpoints)
      .where(eq(chatEndpoints.id, createResponse.body.id));
    expect(stored.assignedAgentId).toBe(fixture.assignedAgentId);
    expect(stored.setup.command).toBe(createdCommand);

    await db
      .update(agents)
      .set({ name: "Maya Renamed" })
      .where(eq(agents.id, fixture.assignedAgentId));
    expect((await service.get(createResponse.body.id)).setup.command).toBe(
      createdCommand,
    );
  });

