  it("orders reversed GitHub edit and delete callbacks behind their durable root", async () => {
    const fixture = await seedCompany();
    const deferred: Array<() => void | Promise<void>> = [];
    const { callbacks, endpoint, service, wakeup, webhookSecret } =
      await configuredGitHubEndpoint(fixture, {
        deferWebhookProcessing: true,
        scheduleDeferredWork: (task) => deferred.push(task),
      });
    const drainDeferred = async () => {
      let processed = 0;
      while (deferred.length > 0) {
        if (processed++ >= 20)
          throw new Error("GitHub deferred test work did not quiesce");
        await deferred.shift()?.();
      }
    };
    const thread = makeThread({
      channelId: "paperclipai/chat-lifecycle-order",
      id: "github:paperclipai/chat-lifecycle-order:issue:84",
      name: "paperclipai/chat-lifecycle-order",
    });
    await db.insert(chatEndpointResources).values({
      companyId: fixture.companyId,
      endpointId: endpoint.id,
      type: "repository",
      providerResourceId: "paperclipai/chat-lifecycle-order",
      label: "paperclipai/chat-lifecycle-order",
      availability: "available",
      enabled: true,
    });
    const original = {
      ...makeMessage({
        id: "99084",
        text: "@maya original ordered GitHub request",
        mentioned: true,
        userId: "7001",
      }),
      metadata: {
        dateSent: new Date("2026-09-05T11:59:59Z"),
        edited: false,
      },
    } as Message;
    await deliverMessage({
      callbacks,
      endpointId: endpoint.id,
      provider: "github",
      thread: thread.thread,
      message: original,
      trigger: "mention",
    });

    const sendLifecycle = (
      action: "edited" | "deleted",
      body: string,
      deliverySuffix = action,
      updatedAt = "2026-09-05T12:00:00Z",
    ) =>
      service.handleWebhook(
        endpoint.publicId,
        "github",
        signedGitHubWebhookRequest({
          delivery: `delivery-84-${deliverySuffix}`,
          event: "issue_comment",
          payload: {
            action,
            comment: {
              id: 99084,
              body,
              updated_at: updatedAt,
            },
            issue: { number: 84 },
            repository: {
              id: 98400,
              full_name: "paperclipai/chat-lifecycle-order",
              name: "chat-lifecycle-order",
              owner: { id: 1357, login: "paperclipai" },
            },
            sender: { id: 7001, login: "alex-e2e" },
          },
          webhookSecret,
          url: `https://paperclip.example/api/chat-webhooks/${endpoint.publicId}/github`,
        }),
      );

    // GitHub may deliver these as independent requests in the opposite order.
    await expect(
      sendLifecycle("deleted", "deleted payload"),
    ).resolves.toMatchObject({ ok: true });
    await expect(
      sendLifecycle("edited", "@maya corrected ordered GitHub request"),
    ).resolves.toMatchObject({
      ok: true,
    });
    // An exact GitHub redelivery id must remain a single durable transition.
    await expect(
      sendLifecycle("edited", "@maya corrected ordered GitHub request"),
    ).resolves.toMatchObject({
      ok: true,
    });

    // One root-conversation drain plus one durable-ingress callback per HTTP
    // request is queued. The duplicate delivery callback becomes a no-op.
    expect(deferred).toHaveLength(4);
    await drainDeferred();
    await vi.waitFor(async () => {
      const deliveries = await db
        .select({
          eventKind: chatDeliveries.eventKind,
          state: chatDeliveries.state,
        })
        .from(chatDeliveries)
        .where(eq(chatDeliveries.endpointId, endpoint.id));
      expect(deliveries).toHaveLength(3);
      expect(
        deliveries.every((delivery) => delivery.state === "processed"),
      ).toBe(true);
    });

    const [conversation] = await db
      .select()
      .from(chatConversations)
      .where(eq(chatConversations.endpointId, endpoint.id));
    const comments = await db
      .select({ body: issueComments.body })
      .from(issueComments)
      .where(eq(issueComments.issueId, conversation.issueId))
      .orderBy(asc(issueComments.createdAt), asc(issueComments.id));
    expect(comments.map((comment) => comment.body)).toEqual([
      "@maya original ordered GitHub request",
      "An external message was edited:\n\n@maya corrected ordered GitHub request",
      "An external message in this conversation was deleted.",
    ]);
    expect(wakeup).toHaveBeenCalledTimes(1);

    await expect(
      sendLifecycle(
        "edited",
        "@maya a delayed edit must not resurrect this message",
        "edited-after-delete",
        "2026-09-05T12:01:00Z",
      ),
    ).resolves.toMatchObject({ ok: true });
    expect(deferred).toHaveLength(1);
    await drainDeferred();
    await vi.waitFor(() => expect(deferred).toHaveLength(1));
    await drainDeferred();
    await vi.waitFor(async () => {
      await expect(
        db
          .select({
            eventKind: chatDeliveries.eventKind,
            redactedError: chatDeliveries.redactedError,
            state: chatDeliveries.state,
          })
          .from(chatDeliveries)
          .where(
            and(
              eq(chatDeliveries.endpointId, endpoint.id),
              eq(chatDeliveries.eventKind, "message_updated"),
              eq(chatDeliveries.state, "filtered"),
            ),
          ),
      ).resolves.toEqual([
        {
          eventKind: "message_updated",
          redactedError:
            "Message edit arrived after the provider message was deleted",
          state: "filtered",
        },
      ]);
    });
    await expect(
      db
        .select({ body: issueComments.body })
        .from(issueComments)
        .where(eq(issueComments.issueId, conversation.issueId)),
    ).resolves.toHaveLength(3);
    expect(wakeup).toHaveBeenCalledTimes(1);
    await service.shutdown();
  });

  it("supplements Chat SDK with verified GitHub comment edit and delete lifecycle events", async () => {
    const fixture = await seedCompany();
    const privateKey = generateKeyPairSync("rsa", { modulusLength: 2048 })
      .privateKey.export({ type: "pkcs8", format: "pem" })
      .toString();
    const runtime = new FakeChatSdkRuntime();
    const { service, wakeup } = createService(runtime, (async (
      input: string | URL | Request,
    ) => {
      const url = String(input);
      if (url === "https://api.github.com/app") {
        return new Response(
          JSON.stringify({
            id: 790,
            slug: "maya-paperclip-lifecycle",
            name: "Maya Paperclip",
            owner: { login: "paperclipai" },
            permissions: {
              issues: "write",
              metadata: "read",
              pull_requests: "write",
            },
            events: [
              "github_app_authorization",
              "installation",
              "installation_repositories",
              "issue_comment",
              "pull_request_review_comment",
            ],
          }),
          { status: 200, headers: { "content-type": "application/json" } },
        );
      }
      if (url === "https://api.github.com/app/installations?per_page=100") {
        return new Response(
          JSON.stringify([
            {
              id: 8642,
              account: { id: 1, login: "paperclipai" },
              permissions: {
                issues: "write",
                metadata: "read",
                pull_requests: "write",
              },
              suspended_at: null,
            },
          ]),
          { status: 200, headers: { "content-type": "application/json" } },
        );
      }
      if (
        url === "https://api.github.com/app/installations/8642/access_tokens"
      ) {
        return new Response(JSON.stringify({ token: "installation-token" }), {
          status: 201,
          headers: { "content-type": "application/json" },
        });
      }
      if (
        url ===
        "https://api.github.com/installation/repositories?per_page=100&page=1"
      ) {
        return new Response(JSON.stringify({ repositories: [] }), {
          status: 200,
          headers: { "content-type": "application/json" },
        });
      }
      throw new Error(`Unexpected provider request: ${url}`);
    }) as typeof globalThis.fetch);
    const endpoint = await service.create(
      fixture.companyId,
      { provider: "github", assignedAgentId: fixture.assignedAgentId },
      "owner-user",
    );
    const { webhookSecret } = await service.generateSetupSecret(
      endpoint.id,
      "owner-user",
    );
    await recordGitHubWebhookVerification(
      service,
      endpoint.publicId,
      webhookSecret,
    );
    await service.configure(
      endpoint.id,
      {
        action: "configure",
        credentials: {
          appId: "123456",
          privateKey,
        },
      },
      "owner-user",
    );
    const callbacks = runtime.configurations.get(endpoint.id)?.callbacks;
    if (!callbacks) throw new Error("Expected GitHub callbacks");
    const thread = makeThread({
      channelId: "paperclipai/chat-e2e",
      id: "github:paperclipai/chat-e2e:issue:42",
      name: "paperclipai/chat-e2e",
    });
    await deliverMessage({
      callbacks,
      endpointId: endpoint.id,
      provider: "github",
      thread: thread.thread,
      message: makeMessage({
        id: "77001",
        text: "@maya original GitHub request",
        mentioned: true,
        userId: "7001",
      }),
      trigger: "mention",
    });
    for (const item of [
      {
        id: "github:paperclipai/chat-e2e:43",
        messageId: "77002",
      },
      {
        id: "github:paperclipai/chat-e2e:43:rc:88001",
        messageId: "88001",
      },
    ]) {
      const nativeThread = makeThread({
        channelId: "paperclipai/chat-e2e",
        id: item.id,
        name: "paperclipai/chat-e2e",
      });
      await deliverMessage({
        callbacks,
        endpointId: endpoint.id,
        provider: "github",
        thread: nativeThread.thread,
        message: makeMessage({
          id: item.messageId,
          text: "@maya original GitHub PR request",
          mentioned: true,
          userId: "7001",
        }),
        trigger: "mention",
      });
    }
    await qualifySetupRoundTrip(service, endpoint.id);
    await service.test(endpoint.id, "owner-user");

    const sendLifecycle = async (input: {
      action: "edited" | "deleted";
      event: "issue_comment" | "pull_request_review_comment";
      messageId: number;
      number: number;
      updatedAt: string;
      body?: string;
      inReplyToId?: number;
      issueIsPullRequest?: boolean;
    }) => {
      await service.handleWebhook(
        endpoint.publicId,
        "github",
        signedGitHubWebhookRequest({
          delivery: `github-comment-${input.event}-${input.messageId}-${input.action}-${input.updatedAt}-${createHash(
            "sha256",
          )
            .update(input.body ?? "@maya corrected GitHub request")
            .digest("hex")
            .slice(0, 12)}`,
          event: input.event,
          payload: {
            action: input.action,
            comment: {
              id: input.messageId,
              in_reply_to_id: input.inReplyToId,
              body: input.body ?? "@maya corrected GitHub request",
              updated_at: input.updatedAt,
            },
            issue: {
              number: input.number,
              pull_request: input.issueIsPullRequest ? {} : undefined,
            },
            pull_request: { number: input.number },
            repository: {
              id: 97531,
              full_name: "paperclipai/chat-e2e",
              name: "chat-e2e",
              owner: { id: 1357, login: "paperclipai" },
            },
            sender: { id: 7001, login: "alex-e2e" },
          },
          webhookSecret,
          url: `https://paperclip.example/api/chat-webhooks/${endpoint.publicId}/github`,
        }),
      );
    };

    for (const input of [
      {
        event: "issue_comment" as const,
        messageId: 77001,
        number: 42,
      },
      {
        event: "issue_comment" as const,
        issueIsPullRequest: true,
        messageId: 77002,
        number: 43,
      },
      {
        event: "pull_request_review_comment" as const,
        inReplyToId: 88001,
        messageId: 88001,
        number: 43,
      },
    ].entries()) {
      const [index, event] = input;
      await sendLifecycle({
        ...event,
        action: "edited",
        updatedAt: `2026-09-05T12:0${index}:00Z`,
      });
      await sendLifecycle({
        ...event,
        action: "deleted",
        updatedAt: `2026-09-05T12:1${index}:00Z`,
      });
    }
    const sameSecondEdit = {
      action: "edited" as const,
      body: "@maya corrected GitHub request again in the same second",
      event: "issue_comment" as const,
      messageId: 77001,
      number: 42,
      updatedAt: "2026-09-05T12:00:00Z",
    };
    await sendLifecycle(sameSecondEdit);
    await sendLifecycle(sameSecondEdit);
    await vi.waitFor(async () => {
      const lifecycle = await db
        .select()
        .from(chatDeliveries)
        .where(eq(chatDeliveries.endpointId, endpoint.id));
      expect(
        lifecycle.filter((row) =>
          ["message_updated", "message_deleted"].includes(row.eventKind),
        ),
      ).toHaveLength(7);
      expect(
        lifecycle.filter(
          (row) =>
            row.eventKind === "message_updated" &&
            row.providerEventId.includes("-77001-"),
        ),
      ).toHaveLength(2);
    });
    expect(wakeup).toHaveBeenCalledTimes(4);
    await service.shutdown();
  });

  it("redacts GitHub edits when the original actor is no longer authorized", async () => {
    const fixture = await seedCompany();
    const { callbacks, endpoint, service, webhookSecret } =
      await configuredGitHubEndpoint(fixture);
    const thread = makeThread({
      channelId: "paperclipai/paperclip",
      id: "github:paperclipai/paperclip:issue:91",
      name: "paperclipai/paperclip",
    });
    await deliverMessage({
      callbacks,
      endpointId: endpoint.id,
      provider: "github",
      thread: thread.thread,
      message: makeMessage({
        id: "99101",
        text: "@maya establish a GitHub task before access changes",
        mentioned: true,
        userId: "7001",
      }),
      trigger: "mention",
    });
    await qualifySetupRoundTrip(service, endpoint.id, "7001");
    await service.test(endpoint.id, "owner-user");
    const [conversation] = await service.listConversations(endpoint.id);
    if (!conversation) throw new Error("Expected GitHub conversation");
    const commentCount = await db
      .select({ id: issueComments.id })
      .from(issueComments)
      .where(eq(issueComments.issueId, conversation.issueId))
      .then((rows) => rows.length);
    await service.update(
      endpoint.id,
      { allowUnlinkedPeople: false },
      "owner-user",
    );

    const revokedEdit = "@maya do not retain this revoked GitHub edit";
    const response = await service.handleWebhook(
      endpoint.publicId,
      "github",
      signedGitHubWebhookRequest({
        delivery: "github-revoked-edit-99101",
        event: "issue_comment",
        payload: {
          action: "edited",
          comment: {
            id: 99101,
            body: revokedEdit,
            updated_at: "2026-09-05T12:20:00Z",
          },
          issue: { number: 91 },
          repository: {
            id: 97531,
            full_name: "paperclipai/paperclip",
            name: "paperclip",
            owner: { id: 1357, login: "paperclipai" },
          },
          sender: { id: 7001, login: "alex-e2e" },
        },
        webhookSecret,
      }),
    );
    expect(response.ok).toBe(true);

    await expect(
      db
        .select({ id: issueComments.id })
        .from(issueComments)
        .where(eq(issueComments.issueId, conversation.issueId)),
    ).resolves.toHaveLength(commentCount);
    const lifecycle = await db
      .select()
      .from(chatDeliveries)
      .where(
        and(
          eq(chatDeliveries.endpointId, endpoint.id),
          eq(chatDeliveries.eventKind, "message_updated"),
        ),
      )
      .then((rows) => rows[0]);
    expect(lifecycle).toMatchObject({
      state: "filtered",
      redactedError:
        "External message actor is no longer authorized for lifecycle events",
      normalizedEvent: { filtering: { contentRetained: false } },
    });
    expect(JSON.stringify(lifecycle?.normalizedEvent)).not.toContain(
      revokedEdit,
    );
    await service.shutdown();
  });

